import{_ as t,o as a,c as o,an as i}from"./chunks/framework.jvHQaJrM.js";const p=JSON.parse('{"title":"Charter and status","description":"","frontmatter":{},"headers":[],"relativePath":"tools/index.md","filePath":"tools/index.md","lastUpdated":null}'),d={name:"tools/index.md"};function r(s,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="charter" tabindex="-1">Charter and status <a class="header-anchor" href="#charter" aria-label="Permalink to &quot;Charter and status {#charter}&quot;">​</a></h1><p>EpiAwareADTools is the EpiAware org&#39;s shared home for AD-safety machinery and AD workarounds. It exists so the same fix is not duplicated across packages, and so each fix has one documented owner.</p><p>Every entry here is a fix we host while we try to fix the underlying problem upstream. Each is documented with the upstream package or issue where it ideally belongs and the condition under which it is deleted. When an upstream fix lands, the matching entry is removed rather than left to rot.</p><h2 id="What-lives-here" tabindex="-1">What lives here <a class="header-anchor" href="#What-lives-here" aria-label="Permalink to &quot;What lives here {#What-lives-here}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Tool</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Upstream target</th><th style="text-align:right;">Deletion condition</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="/v0.1.2/lib/public#EpiAwareADTools.primal"><code>primal</code></a> / <a href="/v0.1.2/lib/public#EpiAwareADTools.primal_distribution"><code>primal_distribution</code></a></td><td style="text-align:right;">Strip an AD wrapper from a scalar or a distribution&#39;s parameters, so a non-differentiable hyperparameter stays off the AD path</td><td style="text-align:right;">No single owner; a per-backend &quot;stop gradient&quot; primitive</td><td style="text-align:right;">A shared stop-gradient primitive covering ForwardDiff, ReverseDiff, Enzyme, and Mooncake</td></tr><tr><td style="text-align:right;"><a href="/v0.1.2/tools/nondifferentiable#nondifferentiable"><code>nondifferentiable</code></a></td><td style="text-align:right;">User-facing opt-out that holds an arbitrary function (or a struct&#39;s constructor) out of differentiation, generalising <code>primal</code>&#39;s discipline to code the caller names</td><td style="text-align:right;">Same as <code>primal</code>/<code>primal_distribution</code>: no single owner for a cross-backend &quot;hold this constant&quot; primitive</td><td style="text-align:right;">Deleted alongside <code>primal</code>/<code>primal_distribution</code> once a shared stop-gradient primitive exists</td></tr><tr><td style="text-align:right;"><a href="/v0.1.2/lib/public#EpiAwareADTools.cdf_ad_safe"><code>cdf_ad_safe</code></a>, <a href="/v0.1.2/lib/public#EpiAwareADTools.logcdf_ad_safe"><code>logcdf_ad_safe</code></a>, <a href="/v0.1.2/lib/public#EpiAwareADTools.ccdf_ad_safe"><code>ccdf_ad_safe</code></a>, <a href="/v0.1.2/lib/public#EpiAwareADTools.logccdf_ad_safe"><code>logccdf_ad_safe</code></a>, <a href="/v0.1.2/lib/public#EpiAwareADTools.pdf_ad_safe"><code>pdf_ad_safe</code></a></td><td style="text-align:right;">Extension-point wrappers whose <code>Gamma</code> and <code>Beta</code> methods stay differentiable in shape/scale</td><td style="text-align:right;"><code>Distributions.jl</code> Gamma/Beta CDF/log-CDF differentiable in their parameters</td><td style="text-align:right;"><code>cdf(::Gamma)</code>/<code>cdf(::Beta)</code> and <code>logcdf(::Gamma)</code>/<code>logcdf(::Beta)</code> differentiable upstream on the supported backends</td></tr><tr><td style="text-align:right;">Gamma-CDF derivative (<code>_gamma_cdf</code> and its rules)</td><td style="text-align:right;">Analytic shape/scale/point partials for <code>P(k, x/θ)</code></td><td style="text-align:right;">Differentiable <code>gamma_inc</code> in <code>SpecialFunctions.jl</code> (<a href="https://github.com/JuliaMath/SpecialFunctions.jl/issues/531" target="_blank" rel="noreferrer">issue #531</a>)</td><td style="text-align:right;"><code>SpecialFunctions.gamma_inc</code> carries a complete <code>ChainRule</code> (the shape partial included)</td></tr><tr><td style="text-align:right;"><a href="/v0.1.2/tools/beta-cdf#beta-cdf">Beta-CDF derivative</a> (<code>_beta_cdf</code> and its rules)</td><td style="text-align:right;">Analytic shape/point partials for <code>I_x(α, β)</code>, the <code>beta_inc</code> analogue of the Gamma-CDF derivative</td><td style="text-align:right;">Differentiable <code>beta_inc</code> in <code>SpecialFunctions.jl</code> (no tracking issue yet)</td><td style="text-align:right;"><code>SpecialFunctions.beta_inc</code> carries a complete <code>ChainRule</code> (the shape partials included)</td></tr><tr><td style="text-align:right;"><a href="/v0.1.2/tools/ad-safe-hooks#survival-hooks">GeneralizedGamma hook methods</a> (<code>SurvivalDistributions</code> extension)</td><td style="text-align:right;">Route a <code>SurvivalDistributions.GeneralizedGamma</code> through the AD-safe Gamma path, and claim the <code>logcdf</code> method the upstream package leaves undefined</td><td style="text-align:right;"><code>SurvivalDistributions.jl</code>, once the Gamma CDF is differentiable in its parameters</td><td style="text-align:right;">The hook family is deleted, i.e. <code>cdf(::Gamma)</code>/<code>logcdf(::Gamma)</code> differentiable upstream</td></tr><tr><td style="text-align:right;"><a href="/v0.1.2/tools/xlogy#xlogy"><code>xlogy</code>/<code>xlog1py</code> Mooncake rules</a> (<code>LogExpFunctions</code> + <code>Mooncake</code> extension)</td><td style="text-align:right;">Lift the <code>LogExpFunctions</code> <code>rrule</code>/<code>frule</code> into Mooncake, so a Gamma log-density differentiated at <code>shape == 1</code> gets <code>log(x / scale)</code> rather than the zero Mooncake derives from the primal&#39;s <code>iszero(x)</code> branch</td><td style="text-align:right;">A rule for <code>xlogy</code>/<code>xlog1py</code> in <code>Mooncake.jl</code>; the report (<a href="https://github.com/chalk-lab/Mooncake.jl/issues/1241" target="_blank" rel="noreferrer">issue #1241</a>) was withdrawn as bot-filed rather than fixed and awaits a re-file</td><td style="text-align:right;"><code>Mooncake</code> registers its own <code>xlogy</code>/<code>xlog1py</code> primitives</td></tr><tr><td style="text-align:right;"><a href="/v0.1.2/tools/logsumexp-stream#logsumexp-stream"><code>logsumexp_stream</code></a></td><td style="text-align:right;">Differentiable, convergence-checked streaming log-sum-exp over an unbounded discrete support, so a heavy tail is never truncated at the first negligible term</td><td style="text-align:right;">No single owner; <code>LogExpFunctions.jl</code>&#39;s <code>logsumexp</code> sums an already-materialised, finite collection rather than streaming an unbounded series with a convergence guarantee</td><td style="text-align:right;"><code>LogExpFunctions.jl</code> (or an equivalent shared numerics package) gains a differentiable streaming accumulator with the same convergence guarantee</td></tr></tbody></table><h2 id="How-to-read-each-page" tabindex="-1">How to read each page <a class="header-anchor" href="#How-to-read-each-page" aria-label="Permalink to &quot;How to read each page {#How-to-read-each-page}&quot;">​</a></h2><p>Each tool family has its own page under this section. A page states the problem the tool works around, shows the public surface, and points at the upstream target so a reader can check whether the workaround is still needed. The <a href="/v0.1.2/lib/public#public-api">Public API</a> and <a href="/v0.1.2/lib/internals#Internal-Documentation">Internal API</a> reference pages carry the full docstrings.</p>',7)])])}const f=t(d,[["render",r]]);export{p as __pageData,f as default};
